1 /* https://leetcode.com/problems/longest-palindromic-substring/
2 Given a string s, return the longest palindromic substring in s.
3 
4 Example 1:
5 Input: s = "babad"
6 Output: "bab"
7 Explanation: "aba" is also a valid answer.
8 */
9 
10 
11 // Specifying the problem: whether `s[i..j]` is palindromic
12 ghost predicate palindromic(s: string, i: int, j: int)
13   requires 0 <= i <= j <= |s|
14   decreases j - i
15 {
16   j - i < 2 || (s[i] == s[j-1] && palindromic(s, i+1, j-1))
17 }
18 
19 // A "common sense" about palindromes:
20 lemma lemma_palindromic_contains(s: string, lo: int, hi: int, lo': int, hi': int)
21   requires 0 <= lo <= lo' <= hi' <= hi <= |s|
22   requires lo + hi == lo' + hi'
23   requires palindromic(s, lo, hi)
24   ensures palindromic(s, lo', hi')
25   decreases lo' - lo
26 {
27   if lo < lo' {
28     lemma_palindromic_contains(s, lo + 1, hi - 1, lo', hi');
29   }
30 }
31 
32 // A useful "helper function" that returns the longest palindrome at a given center (i0, j0).
33 method expand_from_center(s: string, i0: int, j0: int) returns (lo: int, hi: int)
34   requires 0 <= i0 <= j0 <= |s|
35   requires palindromic(s, i0, j0)
36   ensures 0 <= lo <= hi <= |s| && palindromic(s, lo, hi)
37   ensures forall i, j | 0 <= i <= j <= |s| && palindromic(s, i, j)  // Among all palindromes
38     && i + j == i0 + j0                                             // sharing the same center,
39     :: j - i <= hi - lo                                             // `s[lo..hi]` is longest.
40 {
41   lo, hi := i0, j0;
42 
43   // we try expanding whenever possible:
44   while lo - 1 >= 0 && hi < |s| && s[lo - 1] == s[hi]
45     invariant 0 <= lo <= hi <= |s| && lo + hi == i0 + j0
46     invariant palindromic(s, lo, hi)
47   {
48     lo, hi := lo - 1, hi + 1;
49   }
50 
51   // proves that we cannot go further:
52   forall i, j | 0 <= i <= j <= |s| && i + j == i0 + j0 && j - i > hi - lo ensures !palindromic(s, i, j) {
53     if palindromic(s, i, j) { // prove by contradiction:
54       lemma_palindromic_contains(s, i, j, lo - 1, hi + 1);
55     }
56   }
57 }
58 
59 
60 // The main algorithm.
61 // We traverse all centers from left to right, and "expand" each of them, to find the longest palindrome.
62 method longestPalindrome(s: string) returns (ans: string, lo: int, hi: int)
63   ensures 0 <= lo <= hi <= |s| && ans == s[lo..hi]  // `ans` is indeed a substring in `s`
64   ensures palindromic(s, lo, hi)  // `ans` is palindromic
65   ensures forall i, j | 0 <= i <= j <= |s| && palindromic(s, i, j) :: j - i <= hi - lo  // `ans` is longest
66 {
67   lo, hi := 0, 0;
68   for k := 0 to |s|
69     invariant 0 <= lo <= hi <= |s|
70     invariant palindromic(s, lo, hi)
71     invariant forall i, j | 0 <= i <= j <= |s| && i + j < 2 * k && palindromic(s, i, j) :: j - i <= hi - lo
72   {
73     var a, b := expand_from_center(s, k, k);
74     if b - a > hi - lo {
75       lo, hi := a, b;
76     }
77     var c, d := expand_from_center(s, k, k + 1);
78     if d - c > hi - lo {
79       lo, hi := c, d;
80     }
81   }
82   return s[lo..hi], lo, hi;
83 }
