115 // A reference implementation of Manacher's algorithm:
116 // (Ref. https://en.wikipedia.org/wiki/Longest_palindromic_substring#Manacher's_algorithm) for details...
117 method {:vcs_split_on_every_assert} longestPalindrome'(s: string) returns (ans: string, lo: int, hi: int)
118   ensures 0 <= lo <= hi <= |s| && ans == s[lo..hi]
119   ensures palindromic(s, lo, hi)
120   ensures forall i, j | 0 <= i <= j <= |s| && palindromic(s, i, j) :: j - i <= hi - lo
121 {
122   var bogus: char :| true;  // an arbitrary character
123   var s' := insert_bogus_chars(s, bogus);
124   var radii := new int[|s'|];
125   var center, radius := 0, 0;
126   // vars below are just for verifying time complexity:
127   ghost var loop_counter_outer, loop_counter_inner1, loop_counter_inner2 := 0, 0, 0;
128 
129   while center < |s'|
130     invariant 0 <= center <= |s'|
131     invariant forall c | 0 <= c < center :: max_radius(s', c, radii[c])
132     invariant center < |s'| ==> inbound_radius(s', center, radius) && palindromic_radius(s', center, radius)
133     invariant center == |s'| ==> radius == 0
134     invariant loop_counter_outer <= center
135     invariant loop_counter_inner1 <= center + radius && loop_counter_inner2 <= center
136   {
137     loop_counter_outer := loop_counter_outer + 1;
138 
139     // Stage 1: Still the normal "expand from center" routine, except `radius` is NOT necessarily zero:
140     while center - (radius + 1) >= 0 && center + (radius + 1) < |s'|
141         && s'[center - (radius + 1)] == s'[center + (radius + 1)]
142       decreases center - radius
143       invariant inbound_radius(s', center, radius) && palindromic_radius(s', center, radius)
144       invariant loop_counter_inner1 <= center + radius
145     {
146       loop_counter_inner1 := loop_counter_inner1 + 1;
147       radius := radius + 1;
148     }
149     lemma_end_of_expansion(s', center, radius);
150 
151     radii[center] := radius;
152     var old_center, old_radius := center, radius;
153     center := center + 1;
154     radius := 0;
155 
156     // Stage 2: Quickly infer the maximal radius, using the symmetry of known palindromes. 
157     while center <= old_center + old_radius
158       invariant 0 <= center <= |s'|
159       invariant forall c | 0 <= c < center :: max_radius(s', c, radii[c])
160       invariant center < |s'| ==> inbound_radius(s', center, radius) && palindromic_radius(s', center, radius)
161       invariant loop_counter_inner2 <= center - 1
162     {
163       loop_counter_inner2 := loop_counter_inner2 + 1;
164 
165       var mirrored_center := old_center - (center - old_center);
166       var max_mirrored_radius := old_center + old_radius - center;
167       lemma_mirrored_palindrome(s', old_center, old_radius, mirrored_center, radii[mirrored_center], center);
168 
169       if radii[mirrored_center] < max_mirrored_radius {
170         radii[center] := radii[mirrored_center];
171         center := center + 1;
172       } else if radii[mirrored_center] > max_mirrored_radius {
173         radii[center] := max_mirrored_radius;
174         center := center + 1;
175       } else {
176         radius := max_mirrored_radius;
177         break;
178       }
179     }
180   }
181   // verify that the worst time complexity (measured by loop iterations) is O(|s'|) == O(|s|):
182   assert |s'| == 2 * |s| + 1;
183   assert loop_counter_outer <= |s'|;
184   assert loop_counter_inner1 <= |s'|;
185   assert loop_counter_inner2 <= |s'|; 
186 
187   // wrap up results:
188   var (c, r) := argmax(radii, 0);
189   lo, hi := (c - r) / 2, (c + r) / 2; // notice that both ends are bogus chars at position 0, 2, 4, 6, etc.!
190   lemma_result_transfer(s, s', bogus, radii, c, r, hi, lo);
191   return s[lo..hi], lo, hi;        
192 }
