195 // Below are helper functions and lemmas we used:
196 
197 // Inserts bogus characters to the original string (e.g. from `abc` to `|a|b|c|`).
198 // Note that this is neither efficient nor necessary in reality, but just for the ease of understanding.
199 function {:opaque} insert_bogus_chars(s: string, bogus: char): (s': string)
200   ensures |s'| == 2 * |s| + 1
201   ensures forall i | 0 <= i <= |s| :: s'[i * 2] == bogus
202   ensures forall i | 0 <= i < |s| :: s'[i * 2 + 1] == s[i]
203 {
204   if s == "" then
205     [bogus]
206   else
207     var s'_old := insert_bogus_chars(s[1..], bogus);
208     var s'_new := [bogus] + [s[0]] + s'_old;
209     assert forall i | 1 <= i <= |s| :: s'_new[i * 2] == s'_old[(i-1) * 2];
210     s'_new
211 }
212 
213 // Returns (max_index, max_value) of array `a` starting from index `start`.
214 function {:opaque} argmax(a: array<int>, start: int): (res: (int, int))
215   reads a
216   requires 0 <= start < a.Length
217   ensures start <= res.0 < a.Length && a[res.0] == res.1
218   ensures forall i | start <= i < a.Length :: a[i] <= res.1
219   decreases a.Length - start
220 {
221   if start == a.Length - 1 then
222     (start, a[start])
223   else
224     var (i, v) := argmax(a, start + 1);
225     if a[start] >= v then (start, a[start]) else (i, v)
226 }
227 
228 // Whether an interval at center `c` with a radius `r` is within the boundary of `s'`.
229 ghost predicate inbound_radius(s': string, c: int, r: int)
230 {
231   r >= 0 && 0 <= c-r && c+r < |s'|
232 }
233 
234 // Whether `r` is a valid palindromic radius at center `c`.
235 ghost predicate palindromic_radius(s': string, c: int, r: int)
236   requires inbound_radius(s', c, r)
237 {
238   palindromic(s', c-r, c+r+1)
239 }
240 
241 // Whether `r` is the maximal palindromic radius at center `c`.
242 ghost predicate max_radius(s': string, c: int, r: int)
243 {
244   && inbound_radius(s', c, r)
245   && palindromic_radius(s', c, r)
246   && (forall r' | r' > r && inbound_radius(s', c, r') :: !palindromic_radius(s', c, r'))
247 }
248 
249 // Basically, just "rephrasing" the `lemma_palindromic_contains`,
250 // talking about center and radius, instead of interval
251 lemma lemma_palindromic_radius_contains(s': string, c: int, r: int, r': int)
252   requires inbound_radius(s', c, r) && palindromic_radius(s', c, r)
253   requires 0 <= r' <= (r) + 1
254   ensures inbound_radius(s', c, r') && palindromic_radius(s', c, r')
255 {
256   lemma_palindromic_contains(s', c-r, c+r+1, c-r', c+r'+1);
257 }
258 
259 // When "expand from center" ends, we've find the max radius:
260 lemma lemma_end_of_expansion(s': string, c: int, r: int)
261   requires inbound_radius(s', c, r) && palindromic_radius(s', c, r)
262   requires inbound_radius(s', c, r + 1) ==> s'[c - (r + 1)] != s'[c + (r + 1)]
263   ensures max_radius(s', c, r)
264 {
265   forall r' | r' > r && inbound_radius(s', c, r') ensures !palindromic_radius(s', c, r') {
266     if palindromic_radius(s', c, r') {  // proof by contradiction
267       lemma_palindromic_radius_contains(s', c, r', r+1);
268     }
269   }
270 }
