272 // The critical insight behind Manacher's algorithm.
273 //
274 // Given the longest palindrome centered at `c` has length `r`, consider the interval from `c-r` to `c+r`.
275 // Consider a pair of centers in the interval: `c1` (left half) and `c2` (right half), equally away from `c`.
276 // Then, the length of longest palindromes at `c1` and `c2` are related as follows:
277 lemma lemma_mirrored_palindrome(s': string, c: int, r: int, c1: int, r1: int, c2: int)
278   requires max_radius(s', c, r) && max_radius(s', c1, r1)
279   requires c - r <= c1 < c < c2 <= c + r
280   requires c2 - c == c - c1
281   ensures c2 + r1 < c + r ==> max_radius(s', c2, r1)
282   ensures c2 + r1 > c + r ==> max_radius(s', c2, c + r - c2)
283   ensures c2 + r1 == c + r ==> palindromic_radius(s', c2, c + r - c2)
284 {
285   // proof looks long, but is quite straightforward at each step:
286   if c2 + r1 < c + r {
287     for r2 := 0 to r1
288       invariant palindromic_radius(s', c2, r2)
